head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > chooseOptionLabelLocaleRef]<br/>클라이언트 다국어가 적용되었을 때 '선택 안내' 아이템의 Label 로 표시할 텍스트의 Key 값을 설정합니다.",
    "validation" : [
        "chooseOption='true', useLocale='true' 인 경우에 동작합니다.",
        "String 값 설정 시, '선택 안내' 아이템의 Label 로 표시할 텍스트의 Key 값을 설정합니다.",
        "String 값 설정 시, 설정한 Key 값이 JS 파일에 없다면 'global_undefined' 가 적용됩니다.",
        "다국어 기능을 사용하려면 config.xml 파일에서 languagePack 항목을 설정하여야 합니다.",
        "다국어 기능은 Key:Value 형식으로 데이터가 정의된 JS 파일에서 Key 값에 해당하는 Value 값을 찾아 '선택 안내' 아이템의 Label 에 반영합니다.",
        "이때, 클라이언트(웹브라우저)에 설정된 언어에 해당하는 JS 파일이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "4" },
        { "label" : "Sejong", "value" : "2" }
    ]);

    // 전제(chooseOption, useLocale)는 충족값 true, 검증 대상 속성은 JS 파일에 있는 Key 로 초기 선택
    //  gdl_boolean 바인딩 항목의 코드값 : 미설정="1" / true="2" / false="3"
    con_chooseOption.setValue("2");
    con_useLocale.setValue("2");
    con_chooseOptionLabelLocaleRef.setValue("websquare_name");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(DataList 순서) : Incheon(3) / Seoul(1) / Busan(4) / Sejong(2)\n- config.xml 의 languagePack 은 설정되어 있습니다 (ko : /lang/ko.js, en : /lang/en.js)\n- 다국어 Key websquare_name 은 JS 파일에 있는 Key (웹스퀘어(한국어) / WebSquare(영어)), invalid_key 는 JS 파일에 없는 Key 입니다\n[절차] 조건 선택 -> Target 재생성 -> 아이템 확인\n[확인] 영어 JS 파일은 브라우저(웹브라우저) 언어를 en 으로 변경한 뒤 페이지를 다시 열어 확인합니다"', '', 'label1');

    // gdl_boolean 은 getText 로 읽는다 (미설정은 createCList 가 속성에서 제외)
    let properties = {
        chooseOption : con_chooseOption.getText(),
        useLocale : con_useLocale.getText(),
        chooseOptionLabelLocaleRef : con_chooseOptionLabelLocaleRef.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 아이템 인덱스별 Label (Value), 입력창 표시값, 다국어 설정 출력
scwin.btn_getItemInfo_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let objLang = WebSquare.WebSquareLang || {};
    let cLocaleRef = target1.options.chooseOptionLabelLocaleRef;

    // validation 1, 2, 3 판정 출력
    let arrItem = [];
    for (let i = 0; i < target1.getItemCount(); i++) {
        let item = target1.getItem(i);
        arrItem.push("[" + i + "] " + item.label + " (" + item.value + ")");
    }
    bottom.setReturnValue("아이템 : " + arrItem.join(" / "));
    bottom.setReturnValue("입력창 표시값 : " + document.querySelector("[id='" + target1.id + "_label']").textContent);

    // validation 4 판정 출력
    bottom.setReturnValue("다국어 설정 : config languagePack useLanguagePack = "
        + WebSquare.core.getConfiguration("/WebSquare/languagePack/@useLanguagePack")
        + " (로드된 다국어 Key 개수 = " + Object.keys(objLang).length + ")");

    // validation 5, 6 판정 출력
    if (cLocaleRef) {
        bottom.setReturnValue("다국어 JS : 브라우저 언어 = " + navigator.language
            + " / 적용된 언어 = " + WebSquare.systemLanguage
            + " / 적용된 JS 의 lang_type = " + objLang["lang_type"]
            + " / Key " + cLocaleRef + " 의 Value = "
            + ((objLang[cLocaleRef] === undefined) ? "JS 파일에 없음" : objLang[cLocaleRef]));
    }
};
